const ecommerceFaqContent={
nl:[['Wat is TrendMix?','TrendMix is een webshop waar je geselecteerde producten rechtstreeks kunt bekijken en bestellen.'],['Hoe plaats ik een bestelling?','Voeg een product toe aan je winkelwagen, controleer je bestelling en ga verder naar afrekenen.'],['Hoe werkt de betaling?','De betaling wordt tijdens het afrekenen verwerkt via de betaalmethode die op dat moment in TrendMix beschikbaar is.'],['Hoe werkt de levering?','Na betaling wordt je bestelling verwerkt en verzonden naar het door jou opgegeven afleveradres. De actuele levertijd staat bij het product of tijdens het afrekenen.'],['Kan ik mijn bestelling retourneren?','Ja. Voor retouren gelden de retourvoorwaarden van TrendMix. Neem bij een retour- of bestelvraag contact op via het contactformulier.'],['Wat als mijn bestelling beschadigd of verkeerd geleverd is?','Neem zo snel mogelijk contact op met TrendMix en vermeld je bestelgegevens en wat er mis is.'],['Waarom kan prijs of voorraad veranderen?','Voorraad, prijzen en levertijden kunnen wijzigen. De informatie die tijdens het afrekenen wordt getoond is leidend.'],['Hoe kan ik contact opnemen?','Gebruik het contactformulier in de footer. Je bericht wordt naar de klantenservice doorgestuurd.']],
en:[['What is TrendMix?','TrendMix is an online shop where you can browse and order selected products directly.'],['How do I place an order?','Add a product to your cart, review your order and continue to checkout.'],['How does payment work?','Payment is processed during checkout using the payment method currently available on TrendMix.'],['How does delivery work?','After payment, your order is processed and shipped to the delivery address you provide. The current delivery estimate is shown with the product or at checkout.'],['Can I return my order?','Yes. Returns are handled under TrendMix return terms. Use the contact form for a return or order question.'],['What if my order is damaged or incorrect?','Contact TrendMix as soon as possible and include your order details and a description of the problem.'],['Why can price or stock change?','Prices, stock and delivery times can change. The information shown during checkout is the applicable information.'],['How can I contact TrendMix?','Use the contact form in the footer. Your message is forwarded to customer service.']],
fr:[['Qu’est-ce que TrendMix ?','TrendMix est une boutique en ligne où vous pouvez consulter et commander directement des produits sélectionnés.'],['Comment passer une commande ?','Ajoutez un produit au panier, vérifiez votre commande puis passez au paiement.'],['Comment fonctionne le paiement ?','Le paiement est traité lors de la commande avec le moyen de paiement disponible sur TrendMix.'],['Comment fonctionne la livraison ?','Après paiement, la commande est préparée et expédiée à l’adresse indiquée. Le délai actuel est affiché avec le produit ou lors du paiement.'],['Puis-je retourner ma commande ?','Oui. Les retours sont traités selon les conditions de retour de TrendMix. Utilisez le formulaire de contact pour toute demande.'],['Que faire si la commande est endommagée ou incorrecte ?','Contactez TrendMix rapidement avec vos informations de commande et une description du problème.'],['Pourquoi le prix ou le stock peuvent-ils changer ?','Les prix, stocks et délais peuvent changer. Les informations affichées au paiement sont les informations applicables.'],['Comment contacter TrendMix ?','Utilisez le formulaire de contact dans le pied de page. Votre message est transmis au service client.']],
de:[['Was ist TrendMix?','TrendMix ist ein Onlineshop, in dem du ausgewählte Produkte direkt ansehen und bestellen kannst.'],['Wie gebe ich eine Bestellung auf?','Lege ein Produkt in den Warenkorb, prüfe die Bestellung und gehe zur Kasse.'],['Wie funktioniert die Zahlung?','Die Zahlung wird beim Checkout mit der aktuell bei TrendMix verfügbaren Zahlungsmethode verarbeitet.'],['Wie funktioniert die Lieferung?','Nach der Zahlung wird die Bestellung bearbeitet und an die angegebene Lieferadresse versendet. Die aktuelle Lieferzeit steht beim Produkt oder beim Checkout.'],['Kann ich meine Bestellung zurückgeben?','Ja. Für Rückgaben gelten die Rückgabebedingungen von TrendMix. Bei Fragen nutze das Kontaktformular.'],['Was mache ich bei einer beschädigten oder falschen Lieferung?','Kontaktiere TrendMix möglichst schnell mit deinen Bestelldaten und einer Beschreibung des Problems.'],['Warum können Preis oder Bestand sich ändern?','Preise, Bestand und Lieferzeiten können sich ändern. Beim Checkout angezeigte Angaben sind maßgeblich.'],['Wie kann ich TrendMix kontaktieren?','Nutze das Kontaktformular im Footer. Deine Nachricht wird an den Kundenservice weitergeleitet.']],
it:[['Che cos’è TrendMix?','TrendMix è un negozio online dove puoi consultare e ordinare direttamente prodotti selezionati.'],['Come effettuo un ordine?','Aggiungi un prodotto al carrello, controlla l’ordine e procedi al pagamento.'],['Come funziona il pagamento?','Il pagamento viene elaborato durante il checkout con il metodo disponibile su TrendMix.'],['Come funziona la consegna?','Dopo il pagamento, l’ordine viene elaborato e spedito all’indirizzo indicato. I tempi aggiornati sono mostrati sul prodotto o al checkout.'],['Posso restituire un ordine?','Sì. I resi sono gestiti secondo le condizioni di TrendMix. Per una richiesta usa il modulo di contatto.'],['Cosa faccio se l’ordine è danneggiato o errato?','Contatta TrendMix il prima possibile indicando i dati dell’ordine e descrivendo il problema.'],['Perché prezzo o disponibilità possono cambiare?','Prezzi, disponibilità e tempi di consegna possono cambiare. Le informazioni mostrate al checkout sono quelle applicabili.'],['Come posso contattare TrendMix?','Usa il modulo di contatto nel footer. Il messaggio viene inoltrato al servizio clienti.']],
es:[['¿Qué es TrendMix?','TrendMix es una tienda online donde puedes consultar y pedir directamente productos seleccionados.'],['¿Cómo hago un pedido?','Añade un producto al carrito, revisa el pedido y continúa al pago.'],['¿Cómo funciona el pago?','El pago se procesa durante el checkout con el método disponible en TrendMix.'],['¿Cómo funciona la entrega?','Después del pago, el pedido se procesa y se envía a la dirección indicada. El plazo actual aparece en el producto o durante el checkout.'],['¿Puedo devolver mi pedido?','Sí. Las devoluciones se gestionan según las condiciones de TrendMix. Usa el formulario de contacto para cualquier consulta.'],['¿Qué hago si el pedido llega dañado o incorrecto?','Contacta con TrendMix lo antes posible e indica los datos del pedido y el problema.'],['¿Por qué pueden cambiar el precio o el stock?','Los precios, existencias y plazos de entrega pueden cambiar. La información mostrada durante el checkout es la aplicable.'],['¿Cómo puedo contactar con TrendMix?','Usa el formulario de contacto del footer. Tu mensaje se envía al servicio de atención al cliente.']]
};
